            <div style={{ fontSize: '20px', marginBottom: '2px' }}>❓</div>
            <span style={{ fontSize: '9px', fontWeight: 'bold' }}>Help</span>
          </button>
        )}

        <button
          onClick={() => onViewChange('profile')}
          style={{
            background: 'none',
            border: 'none',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            cursor: 'pointer',
            padding: '4px',
            color: currentView === 'profile' ? '#667eea' : '#999',
            minWidth: '60px'
          }}
        >
