                        const reader = new FileReader();
                        reader.onload = (event) => {
                          const newImage = {
                            file: file,
                            url: event.target.result,
                            name: file.name,
                            timestamp: Date.now(),
                            verified: true,
                            verificationQuestion: randomQuestion,
                            verificationAnswer: answer.trim()
                          };
                          updateState({ 
                            selectedImages: [...(appState.selectedImages || []), newImage] 
