                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#ff9800' }}>2.3h</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Avg Response Time</div>
                    </div>
                  </div>

                  <button
                    onClick={() => updateState({ showMyListings: true, showProfile: false })}
                    style={{
                      width: '100%',
                      background: '#667eea',
                      color: 'white',
                      border: 'none',
                      borderRadius: '10px',
                      padding: '12px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      marginTop: '15px'
                    }}
                  >
                    📝 Manage Listings
                </button>
                </div>
              </>
            )}

            <button
              onClick={signOut}
              style={{
                width: '100%',
                background: '#ff4444',
                color: 'white',
                border: 'none',
                borderRadius: '10px',
                padding: '12px',
                fontWeight: 'bold',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px'
              }}
            >
              <LogOut size={16} />
              Sign Out
            </button>
          </div>
        </div>
      )}

      {/* Overlay for profile panel */}
      {appState.showProfile && (
        <div
          style={{
            position: 'fixed',
            top: 'max(0px, env(safe-area-inset-top))',
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            zIndex: 999
          }}
          onClick={() => updateState({ showProfile: false })}
        />
      )}

      {/* Saved Items Modal */}
      {appState.showSavedItems && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.8)',
          zIndex: 1000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '20px'
        }}>
          <div style={{
            background: 'white',
            borderRadius: '20px',
            maxWidth: '500px',
            width: '100%',
            maxHeight: '80vh',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column'
          }}>
            {/* Header */}
            <div style={{
              padding: '20px',
              borderBottom: '1px solid #eee',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between'
            }}>
              <h2 style={{ margin: 0, fontSize: '20px', fontWeight: 'bold' }}>
                💾 Saved Items ({appState.savedItems.length}/{appState.maxDailySaves})
              </h2>
              <button
                onClick={() => updateState({ showSavedItems: false })}
                style={{
                  background: 'none',
                  border: 'none',
                  fontSize: '24px',
                  cursor: 'pointer',
                  color: '#666'
                }}
              >
                ×
              </button>
            </div>

            {/* Search Bar */}
            <div style={{ padding: '15px 20px' }}>
              <input
                type="text"
                placeholder="Search saved items..."
                value={appState.savedItemsSearchQuery}
                onChange={(e) => updateState({ savedItemsSearchQuery: e.target.value })}
                style={{
                  width: '100%',
                  padding: '12px 15px',
                  borderRadius: '10px',
                  border: '1px solid #ddd',
                  fontSize: '16px',
                  outline: 'none'
                }}
              />
            </div>

            {/* Saved Items List */}
            <div style={{
              flex: 1,
              overflowY: 'auto',
              padding: '0 20px 20px'
            }}>
              {appState.savedItems.length === 0 ? (
                <div style={{
                  textAlign: 'center',
                  padding: '40px 20px',
                  color: '#999'
                }}>
                  <p style={{ fontSize: '16px', marginBottom: '10px' }}>No saved items yet</p>
                  <p style={{ fontSize: '14px' }}>Items you save will appear here for easy comparison</p>
                </div>
              ) : (
                appState.savedItems
                  .filter(item => {
                    const query = appState.savedItemsSearchQuery.toLowerCase();
                    return !query || 
                      item.title.toLowerCase().includes(query) ||
                      item.description.toLowerCase().includes(query) ||
                      item.price.toString().includes(query);
                  })
                  .map((item, index) => (
                    <div key={item.id} style={{
                      display: 'flex',
                      gap: '15px',
                      padding: '15px',
                      background: '#f9f9f9',
                      borderRadius: '12px',
                      marginBottom: '10px',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease'
                    }}>
                      <img
                        src={item.image_url}
                        alt={item.title}
                        style={{
                          width: '80px',
                          height: '80px',
                          objectFit: 'cover',
                          borderRadius: '8px'
                        }}
                      />
                      <div style={{ flex: 1 }}>
                        <h3 style={{
                          margin: '0 0 5px 0',
                          fontSize: '16px',
                          fontWeight: '600',
                          color: '#333'
                        }}>
                          {item.title}
                        </h3>
                        <p style={{
                          margin: '0 0 5px 0',
                          fontSize: '18px',
                          fontWeight: 'bold',
                          color: '#4CAF50'
                        }}>
                          ${item.price}
                        </p>
                        <p style={{
                          margin: 0,
                          fontSize: '12px',
                          color: '#999'
                        }}>
                          Saved {new Date(item.savedAt).toLocaleDateString()}
                        </p>
                      </div>
                      <div style={{ 
                        display: 'flex', 
                        flexDirection: 'column', 
                        gap: '8px',
                        alignSelf: 'flex-start'
                      }}>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            // Use proper interest flow instead of bypassing seller approval
                            handleExpressInterest(item);
                            updateState({ showSavedItems: false });
                          }}
                          style={{
                            background: '#667eea',
                            color: 'white',
                            border: 'none',
                            borderRadius: '6px',
                            padding: '6px 10px',
                            fontSize: '11px',
                            cursor: 'pointer',
                            fontWeight: 'bold'
                          }}
                        >
                          💝 Interest
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            const newSavedItems = appState.savedItems.filter(i => i.id !== item.id);
                            updateState({ savedItems: newSavedItems });
                          }}
                          style={{
                            background: '#ff4444',
                            color: 'white',
                            border: 'none',
                            borderRadius: '6px',
                            padding: '6px 10px',
                            fontSize: '11px',
                            cursor: 'pointer',
                            fontWeight: 'bold'
                          }}
                        >
                          🗑️ Remove
                        </button>
                      </div>
                    </div>
                  ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Daily Limit Modal */}
      {appState.showLimitModal && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.8)',
          zIndex: 1001,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '20px'
        }}>
          <div style={{
            background: 'white',
            borderRadius: '20px',
            padding: '30px',
            maxWidth: '400px',
            width: '100%',
            textAlign: 'center'
          }}>
            <h2 style={{ marginBottom: '15px', color: '#ff9800' }}>
              🚫 Daily Limit Reached
            </h2>
            <p style={{ marginBottom: '20px', color: '#666' }}>
              {appState.limitModalType === 'saves' 
                ? `You've reached your daily limit of ${appState.maxDailySaves} saves.`
                : appState.limitModalType === 'swipes'
                ? `You've reached your daily limit of ${appState.maxDailySwipes} swipes.`
                : `You've reached your daily limit of ${appState.maxDailyLikes} likes.`
              }
              <br />
              Come back tomorrow to continue!
            </p>
            <button
              onClick={() => updateState({ showLimitModal: false, limitModalType: null })}
              style={{
                background: '#667eea',
                color: 'white',
                border: 'none',
                borderRadius: '25px',
                padding: '12px 30px',
                fontSize: '16px',
                fontWeight: 'bold',
                cursor: 'pointer'
              }}
            >
              Got it!
            </button>
          </div>
        </div>
      )}

      {/* Report Modal */}
      {appState.showReportModal && appState.reportingItem && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.8)',
          zIndex: 1001,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '20px'
        }}>
          <div style={{
            background: 'white',
            borderRadius: '20px',
            padding: '30px',
            maxWidth: '400px',
            width: '100%',
            textAlign: 'center'
          }}>
            <div style={{ fontSize: '40px', marginBottom: '20px' }}>🚩</div>
            <h2 style={{ color: '#ff5722', marginBottom: '15px', fontSize: '22px' }}>
              Report Listing
            </h2>
            <p style={{ color: '#666', marginBottom: '25px', fontSize: '14px' }}>
              Why are you reporting "{appState.reportingItem.title}"?
            </p>

            <div style={{ textAlign: 'left', marginBottom: '25px' }}>
              {[
                'Fake/stolen photos',
                'Spam/duplicate listing', 
                'Inappropriate content',
                'Suspected bot/scam',
                'Wrong category/misleading',
                'Other'
              ].map((reason) => (
                <label key={reason} style={{
                  display: 'flex',
                  alignItems: 'center',
                  marginBottom: '12px',
                  cursor: 'pointer',
                  padding: '8px',
                  borderRadius: '8px',
                  background: appState.selectedReportReason === reason ? '#f3f4f6' : 'transparent'
                }}>
                  <input
                    type="radio"
                    name="reportReason"
                    value={reason}
                    checked={appState.selectedReportReason === reason}
                    onChange={(e) => updateState({ selectedReportReason: e.target.value })}
                    style={{ marginRight: '12px', transform: 'scale(1.2)' }}
                  />
                  <span style={{ fontSize: '14px' }}>{reason}</span>
                </label>
              ))}
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                onClick={() => updateState({ 
                  showReportModal: false, 
                  reportingItem: null, 
                  selectedReportReason: '' 
                })}
                style={{
                  flex: 1,
                  background: '#e0e0e0',
                  color: '#666',
                  border: 'none',
                  borderRadius: '25px',
                  padding: '12px 20px',
                  fontSize: '14px',
                  fontWeight: 'bold',
                  cursor: 'pointer'
                }}
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  if (!appState.selectedReportReason) {
                    alert('Please select a reason for reporting.');
                    return;
                  }

                  const newReportedItems = new Set(appState.reportedItems);
                  newReportedItems.add(appState.reportingItem.id);

                  updateState({
                    reportedItems: newReportedItems,
                    userReportCount: appState.userReportCount + 1,
                    showReportModal: false,
                    reportingItem: null,
                    selectedReportReason: ''
                  });

                  console.log(`🚨 Reported item: ${appState.reportingItem.title} for: ${appState.selectedReportReason}`);
                  alert('Thank you for your report. We will review this item.');
                }}
                disabled={!appState.selectedReportReason}
                style={{
                  flex: 1,
                  background: appState.selectedReportReason ? '#ff5722' : '#ccc',
                  color: 'white',
                  border: 'none',
                  borderRadius: '25px',
                  padding: '12px 20px',
                  fontSize: '14px',
                  fontWeight: 'bold',
                  cursor: appState.selectedReportReason ? 'pointer' : 'not-allowed'
                }}
              >
                Submit Report
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Navigation - Always visible when authenticated */}
      <BottomNavigation 
        currentView={appState.currentView}
        currentMode={appState.currentMode}
        onViewChange={(view) => {
          console.log('Changing view to:', view);
          updateState({ 
            currentView: view,
            showChats: view === 'chats',
            showProfile: view === 'profile'
          });
        }}
        onModeChange={(mode) => {
          console.log('Changing mode to:', mode);

          // Show swipe tutorial when entering buy mode for the first time
          if (mode === 'buyer' && !appState.hasSeenBuyModeTutorial) {
            updateState({ currentMode: mode, showSwipeTutorial: true });
          } else {
            updateState({ currentMode: mode });
          }
        }}
        onShowTutorial={showSwipeTutorial}
      />

      {/* Animation Components */}
      <SwipeFeedback type={showSwipeFeedback} show={showSwipeFeedback !== null} />
      {/* No match animation - this is a marketplace, not a dating app! */}

      {/* Mobile Controls - Admin Access - Hide when profile is open or add item form is open */}
      {!appState.showProfile && !appState.showAddItem && (
        <div style={{
          position: 'fixed',
          top: /android/i.test(navigator.userAgent) || window.Capacitor?.getPlatform?.() === 'android'
            ? '30px' // Lower on Android to avoid status bar overlap
            : '10px', // Original iOS position
          right: '10px',
          zIndex: 9999,
          display: 'flex',
          flexDirection: 'column',
          gap: '8px'
        }}>
          {/* Admin Dashboard Access for Mobile */}
          <div style={{
            background: '#ff9800',
            color: 'white',
            padding: '8px 12px',
            borderRadius: '20px',
            fontSize: '12px',
            cursor: 'pointer',
            boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
            textAlign: 'center'
          }}
          onClick={() => updateState({ showAdminDashboard: !appState.showAdminDashboard })}>
            📊 Admin
          </div>
        </div>
      )}
    </>
  );
};

const App = () => (
  <AuthProvider>
    <SwipeMarketplace />
  </AuthProvider>
);

export default App;
